const fs=require('fs'),p=require('path'),c=require('crypto'),b=process.argv[2],rd=n=>JSON.parse(fs.readFileSync(p.join(b,n),'utf8').replace(/^\uFEFF/,'')),sha=x=>c.createHash('sha256').update(x).digest('hex');const report={};let bad=[];
for(const i of ['01','02','03','04','05']){let zone='A'+i,n=zone+'_raport.json',d=rd(n),plan=rd('../'+zone+'_plan.json'),ctrl=plan.controls||plan.controale||plan.checklists,pipe=plan.pipelines||plan.pipelineuri||plan.pipeline_catalog||plan.pipeline;let hchecks=0, declared=[];const check=(key,path,h)=>{const loc=path.replace(/^executie[\\/]/,'');let fn=p.join(b,loc);let ok=fs.existsSync(fn)&&(h?sha(fs.readFileSync(fn))===h:true);declared.push({key,file:loc,hash_checked:!!h,ok});if(!ok)bad.push([zone,key,loc]);hchecks+=h?1:0;};
if(i==='01'){for(const [k,h] of Object.entries(d.artifacts_sha256))check(k,zone+'/'+k,h);for(const [k,ev] of Object.entries(d.evidence_index))if(ev.file)check(k,ev.file,null)}
if(i==='02'){for(const z of d.probe_index)check(z.id,z.file,z.sha256)}
if(i==='03'||i==='04')for(const [k,v] of Object.entries(d.evidence_index))check(k,v.path,v.sha256)
if(i==='05')for(const [k,x] of Object.entries(d.evidence_index)){if(typeof x==='string')check(k,x,null);else if(x.artifacts)for(const v of x.artifacts)check(k,v.file,v.sha256);else if(x.file)check(k,x.file,x.sha256)}
const setdiff=(u,v)=>u.filter(x=>!v.includes(x));let ci=d.controls.map(x=>x.control_id||x.id),pi=d.pipelines.map(x=>x.pipeline_id||x.id),parentC=ctrl.map(x=>x.id||x.control_id),parentP=pipe.map(x=>x.id||x.pipeline_id),find=d.findings.map(x=>x.finding_id||x.id);let dx={controls_missing:setdiff(parentC,ci),controls_extra:setdiff(ci,parentC),pipes_missing:setdiff(parentP,pi),pipes_extra:setdiff(pi,parentP)};const st={};for(const x of d.controls)st[x.status]=(st[x.status]||0)+1;report[zone]={hash:sha(fs.readFileSync(p.join(b,n))),controls:ci.length,pipes:pi.length,findings:find,reference_hash_checks:hchecks,reference_paths:declared.length,structure:dx,control_states:st,issues:bad.filter(x=>x[0]===zone)};}console.log(JSON.stringify(report));fs.writeFileSync(p.join(b,'A11_reproduceri_lot1','rapoarte_integritate.json'),JSON.stringify(report,null,2)+'\n');
